-- Hand-written, per-beach SEO titles, descriptions and editorial copy for the
-- 113 Mexico beach pages, plus five reviewed Wikimedia Commons area photos.
-- Source copy: docs/imports/baja-surf-spots/2026-09-16/mexico-beach-copy.json
-- seo_indexable and editorial_reviewed_at are intentionally unchanged; they
-- remain a separate human editorial approval step.

BEGIN;

CREATE TEMP TABLE _mexico_beach_copy (
  beach_id uuid,
  slug text NOT NULL,
  seo_title text NOT NULL,
  seo_description text NOT NULL,
  description text NOT NULL,
  wave_tips text NOT NULL,
  access_tips text NOT NULL,
  best_conditions_prose text NOT NULL
) ON COMMIT DROP;


-- Teresa's predates the Baja import and has no stable import id.
UPDATE _mexico_beach_copy c
SET beach_id = b.id
FROM public.beaches b
WHERE c.beach_id IS NULL
  AND b.slug = c.slug
  AND b.country = 'Mexico'
  AND b.deleted_at IS NULL;

DO $$
DECLARE
  unresolved integer;
  matched integer;
BEGIN
  SELECT count(*) INTO unresolved
  FROM _mexico_beach_copy c
  WHERE c.beach_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.beaches b
       WHERE b.id = c.beach_id AND b.country = 'Mexico' AND b.slug = c.slug
     );
  IF unresolved <> 0 THEN
    RAISE EXCEPTION 'Mexico beach copy: % rows do not match a Mexico beach by id and slug', unresolved;
  END IF;

  UPDATE public.beaches b
  SET seo_title = c.seo_title,
      seo_description = c.seo_description,
      description = c.description,
      wave_tips = c.wave_tips,
      access_tips = c.access_tips,
      best_conditions_prose = c.best_conditions_prose
  FROM _mexico_beach_copy c
  WHERE b.id = c.beach_id;
  GET DIAGNOSTICS matched = ROW_COUNT;
  IF matched <> 113 THEN
    RAISE EXCEPTION 'Mexico beach copy: expected 113 updates, got %', matched;
  END IF;
END;
$$;

  beach_id, source, source_id, image_url, thumb_url, title,
  creator_name, creator_url, license_code, license_url, attribution_html,
  approved, fetched_at
)
SELECT v.beach_id, 'wikimedia', v.source_id, v.image_url, v.thumb_url, v.title,
       v.creator_name, v.creator_url, v.license_code, v.license_url, v.attribution_html,
       true, now()
FROM (VALUES
  ('2394a731-17a2-58a6-ab5b-2b445b525f76'::uuid, '47813259', 'https://upload.wikimedia.org/wikipedia/commons/c/c1/Coastline_south_of_Tijuana_-_panoramio.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Coastline_south_of_Tijuana_-_panoramio.jpg/1280px-Coastline_south_of_Tijuana_-_panoramio.jpg', 'Coastline south of Tijuana, near San Antonio del Mar', 'Alistair Cunningham', 'https://commons.wikimedia.org/?curid=47813259', 'CC BY 3.0', 'https://creativecommons.org/licenses/by/3.0', 'Photo: <a href="https://commons.wikimedia.org/?curid=47813259">Coastline south of Tijuana - panoramio.jpg</a> by Alistair Cunningham, <a href="https://creativecommons.org/licenses/by/3.0">CC BY 3.0</a>, via Wikimedia Commons. Shows the surrounding area, not necessarily the break.'),
  ('f3750657-2f49-5a07-a9c9-0c80c7d628ef'::uuid, '65581081', 'https://upload.wikimedia.org/wikipedia/commons/8/84/Popotla_fishing_village_2015.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/84/Popotla_fishing_village_2015.jpg', 'Popotla fishing village', 'FOODHOE', 'https://commons.wikimedia.org/?curid=65581081', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'Photo: <a href="https://commons.wikimedia.org/?curid=65581081">Popotla fishing village 2015.jpg</a> by FOODHOE, <a href="https://creativecommons.org/licenses/by-sa/3.0">CC BY-SA 3.0</a>, via Wikimedia Commons. Shows the surrounding area, not necessarily the break.'),
  ('63092ce4-b394-5274-a70e-5bac21548139'::uuid, '47813294', 'https://upload.wikimedia.org/wikipedia/commons/9/96/Coastline_north_of_Ensenada_-_panoramio.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Coastline_north_of_Ensenada_-_panoramio.jpg/1280px-Coastline_north_of_Ensenada_-_panoramio.jpg', 'Coastline north of Ensenada', 'Alistair Cunningham', 'https://commons.wikimedia.org/?curid=47813294', 'CC BY 3.0', 'https://creativecommons.org/licenses/by/3.0', 'Photo: <a href="https://commons.wikimedia.org/?curid=47813294">Coastline north of Ensenada - panoramio.jpg</a> by Alistair Cunningham, <a href="https://creativecommons.org/licenses/by/3.0">CC BY 3.0</a>, via Wikimedia Commons. Shows the surrounding area, not necessarily the break.'),
  ('eceeb33f-1bc6-5fe4-b3b0-b6b5610849fe'::uuid, '90169045', 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Piedras_apiladas_en_playa_San_Miguel%2C_Ensenada_Baja_California.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Piedras_apiladas_en_playa_San_Miguel%2C_Ensenada_Baja_California.jpg/1280px-Piedras_apiladas_en_playa_San_Miguel%2C_Ensenada_Baja_California.jpg', 'Cobblestone shore at Playa San Miguel, Ensenada', 'Alexandra Valtierra Soto', 'https://commons.wikimedia.org/?curid=90169045', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'Photo: <a href="https://commons.wikimedia.org/?curid=90169045">Piedras apiladas en playa San Miguel, Ensenada Baja California.jpg</a> by Alexandra Valtierra Soto, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a>, via Wikimedia Commons. Shows the surrounding area, not necessarily the break.'),
  ('dd0c6e3e-6c47-5be2-804b-a9b4a49b603f'::uuid, '34485264', 'https://upload.wikimedia.org/wikipedia/commons/6/6b/El_Pescadero_beach_2013-03-12.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/6b/El_Pescadero_beach_2013-03-12.jpg', 'El Pescadero beach', 'Andrea Tosatto from Torino, Italia', 'https://commons.wikimedia.org/?curid=34485264', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'Photo: <a href="https://commons.wikimedia.org/?curid=34485264">El Pescadero beach 2013-03-12.jpg</a> by Andrea Tosatto from Torino, Italia, <a href="https://creativecommons.org/licenses/by/2.0">CC BY 2.0</a>, via Wikimedia Commons. Shows the surrounding area, not necessarily the break.')
) AS v(beach_id, source_id, image_url, thumb_url, title, creator_name, creator_url, license_code, license_url, attribution_html)
JOIN public.beaches b ON b.id = v.beach_id AND b.country = 'Mexico'
ON CONFLICT (beach_id, source, source_id) DO NOTHING;

COMMIT;
